import React, { useEffect, useRef, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiBookOpen,
  FiLayers,
  FiUploadCloud,
  FiX,
  FiCheckCircle,
  FiXCircle,
  FiStar,
  FiImage,
  FiGlobe,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';

const initialCourseForm = {
  title_en: '',
  description_en: '',
  short_description_en: '',
  duration_en: '',
  level_en: '',

  title_km: '',
  description_km: '',
  short_description_km: '',
  duration_km: '',
  level_km: '',

  slug: '',
  category_id: '',
  price: '',
  is_active: true,
  is_featured: false,
  order: 0,
};

const initialCategoryForm = {
  name_en: '',
  description_en: '',

  name_km: '',
  description_km: '',

  slug: '',
  is_active: true,
  order: 0,
};

const AdminCourses = () => {
  const { t, language } = useLanguage();

  const isKhmer = language === 'km' || language === 'kh';
  const langSuffix = isKhmer ? 'km' : 'en';

  const tr = (key, englishFallback, khmerFallback) => {
    const translated = t(key);

    if (translated && translated !== key) {
      return translated;
    }

    return isKhmer ? khmerFallback : englishFallback;
  };

  const [activeTab, setActiveTab] = useState('courses');

  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  const [courseModalOpen, setCourseModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [courseSubmitting, setCourseSubmitting] = useState(false);

  const [courseFormData, setCourseFormData] = useState({
    ...initialCourseForm,
  });

  const [courseImageFile, setCourseImageFile] = useState(null);
  const [courseImagePreview, setCourseImagePreview] = useState('');

  const courseFileRef = useRef(null);

  const [categoryModalOpen, setCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [categorySubmitting, setCategorySubmitting] = useState(false);

  const [categoryFormData, setCategoryFormData] = useState({
    ...initialCategoryForm,
  });

  const [categoryImageFile, setCategoryImageFile] = useState(null);
  const [categoryImagePreview, setCategoryImagePreview] = useState('');

  const categoryFileRef = useRef(null);

  const API_BASE_URL =
    process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  const getImageUrl = (image) => {
    if (!image) {
      return '';
    }

    if (
      image.startsWith('http://') ||
      image.startsWith('https://') ||
      image.startsWith('blob:') ||
      image.startsWith('data:')
    ) {
      return image;
    }

    return `${API_BASE_URL}${image.startsWith('/') ? '' : '/'}${image}`;
  };

  const getCourseValue = (course, field) => {
    if (!course) {
      return '';
    }

    if (isKhmer) {
      return course[`${field}_km`] || course[`${field}_en`] || '';
    }

    return course[`${field}_en`] || course[`${field}_km`] || '';
  };

  const getCategoryValue = (category, field) => {
    if (!category) {
      return '';
    }

    if (isKhmer) {
      return category[`${field}_km`] || category[`${field}_en`] || '';
    }

    return category[`${field}_en`] || category[`${field}_km`] || '';
  };

  const getCourseCategoryName = (course) => {
    if (course?.category) {
      const name = getCategoryValue(course.category, 'name');

      if (name) {
        return name;
      }
    }

    const category = categories.find(
      (item) => String(item.id) === String(course?.category_id)
    );

    if (!category) {
      return tr(
        'courses.noCategory',
        'No Category',
        'គ្មានប្រភេទ'
      );
    }

    return (
      getCategoryValue(category, 'name') ||
      tr(
        'courses.noCategory',
        'No Category',
        'គ្មានប្រភេទ'
      )
    );
  };

  const createSlug = (value = '') => {
    return String(value)
      .toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
  };

  const fetchData = async () => {
    try {
      setLoading(true);

      const [coursesResponse, categoriesResponse] = await Promise.all([
        api.get('/api/courses/'),
        api.get('/api/courses/categories/all'),
      ]);

      setCourses(
        Array.isArray(coursesResponse.data)
          ? coursesResponse.data
          : coursesResponse.data?.items || []
      );

      setCategories(
        Array.isArray(categoriesResponse.data)
          ? categoriesResponse.data
          : categoriesResponse.data?.items || []
      );
    } catch (error) {
      console.error('Fetch courses error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.loadFailed',
            'Failed to load courses and categories.',
            'មិនអាចទាញយកវគ្គសិក្សា និងប្រភេទវគ្គសិក្សាបានទេ។'
          )
        )
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    return () => {
      if (
        courseImagePreview &&
        courseImagePreview.startsWith('blob:')
      ) {
        URL.revokeObjectURL(courseImagePreview);
      }

      if (
        categoryImagePreview &&
        categoryImagePreview.startsWith('blob:')
      ) {
        URL.revokeObjectURL(categoryImagePreview);
      }
    };
  }, [courseImagePreview, categoryImagePreview]);

  const resetCourseForm = () => {
    setEditingCourse(null);

    setCourseFormData({
      ...initialCourseForm,
    });

    setCourseImageFile(null);

    if (
      courseImagePreview &&
      courseImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(courseImagePreview);
    }

    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };

  const handleAddCourse = () => {
    resetCourseForm();
    setCourseModalOpen(true);
  };

  const closeCourseModal = () => {
    if (courseSubmitting) {
      return;
    }

    setCourseModalOpen(false);
    resetCourseForm();
  };

  const handleCourseInputChange = (event) => {
    const { name, value, type, checked } = event.target;

    setCourseFormData((previous) => {
      const updated = {
        ...previous,
        [name]: type === 'checkbox' ? checked : value,
      };

      if (
        name === 'title_en' &&
        !editingCourse
      ) {
        updated.slug = createSlug(value);
      }

      return updated;
    });
  };

  const handleCourseImageChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (!allowedTypes.includes(file.type)) {
      toast.error(
        tr(
          'courses.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាពប្រភេទ JPG, JPEG, PNG ឬ WEBP។'
        )
      );

      event.target.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error(
        tr(
          'courses.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value = '';
      return;
    }

    if (
      courseImagePreview &&
      courseImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(courseImagePreview);
    }

    const preview = URL.createObjectURL(file);

    setCourseImageFile(file);
    setCourseImagePreview(preview);
  };

  const removeCourseImage = () => {
    if (
      courseImagePreview &&
      courseImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(courseImagePreview);
    }

    setCourseImageFile(null);
    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };

  const handleEditCourse = (course) => {
    setEditingCourse(course);

    setCourseFormData({
      title_en: course.title_en || '',
      description_en: course.description_en || '',
      short_description_en: course.short_description_en || '',
      duration_en: course.duration_en || '',
      level_en: course.level_en || '',

      title_km: course.title_km || '',
      description_km: course.description_km || '',
      short_description_km: course.short_description_km || '',
      duration_km: course.duration_km || '',
      level_km: course.level_km || '',

      slug: course.slug || '',

      category_id: course.category_id
        ? String(course.category_id)
        : '',

      price: course.price ?? '',
      is_active: course.is_active ?? true,
      is_featured: course.is_featured ?? false,
      order: course.order ?? 0,
    });

    setCourseImageFile(null);

    setCourseImagePreview(
      getImageUrl(course.image_url || '')
    );

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }

    setCourseModalOpen(true);
  };

  const handleCourseSubmit = async (event) => {
    event.preventDefault();

    const currentTitle =
      courseFormData[`title_${langSuffix}`]?.trim();

    if (!currentTitle) {
      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលចំណងជើងវគ្គសិក្សា។'
          : 'Course title is required.'
      );

      return;
    }

    if (!courseFormData.slug.trim()) {
      toast.error(
        tr(
          'courses.slugRequired',
          'Course slug is required.',
          'សូមបញ្ចូល Slug របស់វគ្គសិក្សា។'
        )
      );

      return;
    }

    if (!courseFormData.category_id) {
      toast.error(
        tr(
          'courses.categoryRequired',
          'Please select a course category.',
          'សូមជ្រើសរើសប្រភេទវគ្គសិក្សា។'
        )
      );

      return;
    }

    try {
      setCourseSubmitting(true);

      const payload = new FormData();

      const titleEn =
        courseFormData.title_en.trim() ||
        currentTitle;

      const titleKm =
        courseFormData.title_km.trim() ||
        currentTitle;

      payload.append(
        'title_en',
        titleEn
      );

      payload.append(
        'description_en',
        courseFormData.description_en.trim()
      );

      payload.append(
        'short_description_en',
        courseFormData.short_description_en.trim()
      );

      payload.append(
        'duration_en',
        courseFormData.duration_en.trim()
      );

      payload.append(
        'level_en',
        courseFormData.level_en.trim()
      );

      payload.append(
        'title_km',
        titleKm
      );

      payload.append(
        'description_km',
        courseFormData.description_km.trim()
      );

      payload.append(
        'short_description_km',
        courseFormData.short_description_km.trim()
      );

      payload.append(
        'duration_km',
        courseFormData.duration_km.trim()
      );

      payload.append(
        'level_km',
        courseFormData.level_km.trim()
      );

      payload.append(
        'slug',
        createSlug(courseFormData.slug)
      );

      payload.append(
        'category_id',
        String(courseFormData.category_id)
      );

      payload.append(
        'price',
        String(courseFormData.price || '')
      );

      payload.append(
        'is_active',
        String(courseFormData.is_active)
      );

      payload.append(
        'is_featured',
        String(courseFormData.is_featured)
      );

      payload.append(
        'order',
        String(Number(courseFormData.order) || 0)
      );

      if (courseImageFile) {
        payload.append(
          'image_file',
          courseImageFile
        );
      }

      if (editingCourse) {
        await api.put(
          `/api/courses/${editingCourse.id}`,
          payload
        );

        toast.success(
          tr(
            'courses.updatedSuccess',
            'Course updated successfully.',
            'បានកែប្រែវគ្គសិក្សាដោយជោគជ័យ។'
          )
        );
      } else {
        await api.post(
          '/api/courses/',
          payload
        );

        toast.success(
          tr(
            'courses.createdSuccess',
            'Course created successfully.',
            'បានបង្កើតវគ្គសិក្សាដោយជោគជ័យ។'
          )
        );
      }

      setCourseModalOpen(false);
      resetCourseForm();

      await fetchData();
    } catch (error) {
      console.error(
        'Save course error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.saveFailed',
            'Failed to save course.',
            'មិនអាចរក្សាទុកវគ្គសិក្សាបានទេ។'
          )
        )
      );
    } finally {
      setCourseSubmitting(false);
    }
  };

  const handleDeleteCourse = async (id) => {
    const confirmed = window.confirm(
      tr(
        'courses.deleteConfirm',
        'Are you sure you want to delete this course?',
        'តើអ្នកប្រាកដថាចង់លុបវគ្គសិក្សានេះមែនទេ?'
      )
    );

    if (!confirmed) {
      return;
    }

    try {
      await api.delete(
        `/api/courses/${id}`
      );

      toast.success(
        tr(
          'courses.deletedSuccess',
          'Course deleted successfully.',
          'បានលុបវគ្គសិក្សាដោយជោគជ័យ។'
        )
      );

      await fetchData();
    } catch (error) {
      console.error(
        'Delete course error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.deleteFailed',
            'Failed to delete course.',
            'មិនអាចលុបវគ្គសិក្សាបានទេ។'
          )
        )
      );
    }
  };

  const resetCategoryForm = () => {
    setEditingCategory(null);

    setCategoryFormData({
      ...initialCategoryForm,
    });

    setCategoryImageFile(null);

    if (
      categoryImagePreview &&
      categoryImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(categoryImagePreview);
    }

    setCategoryImagePreview('');

    if (categoryFileRef.current) {
      categoryFileRef.current.value = '';
    }
  };

  const handleAddCategory = () => {
    resetCategoryForm();
    setCategoryModalOpen(true);
  };

  const closeCategoryModal = () => {
    if (categorySubmitting) {
      return;
    }

    setCategoryModalOpen(false);
    resetCategoryForm();
  };

  const handleCategoryInputChange = (event) => {
    const { name, value, type, checked } = event.target;

    setCategoryFormData((previous) => {
      const updated = {
        ...previous,
        [name]: type === 'checkbox' ? checked : value,
      };

      if (
        name === 'name_en' &&
        !editingCategory
      ) {
        updated.slug = createSlug(value);
      }

      return updated;
    });
  };

  const handleCategoryImageChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (!allowedTypes.includes(file.type)) {
      toast.error(
        tr(
          'courses.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាពប្រភេទ JPG, JPEG, PNG ឬ WEBP។'
        )
      );

      event.target.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error(
        tr(
          'courses.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );

      event.target.value = '';
      return;
    }

    if (
      categoryImagePreview &&
      categoryImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(categoryImagePreview);
    }

    const preview = URL.createObjectURL(file);

    setCategoryImageFile(file);
    setCategoryImagePreview(preview);
  };

  const removeCategoryImage = () => {
    if (
      categoryImagePreview &&
      categoryImagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(categoryImagePreview);
    }

    setCategoryImageFile(null);
    setCategoryImagePreview('');

    if (categoryFileRef.current) {
      categoryFileRef.current.value = '';
    }
  };

  const handleEditCategory = (category) => {
    setEditingCategory(category);

    setCategoryFormData({
      name_en: category.name_en || '',
      description_en: category.description_en || '',

      name_km: category.name_km || '',
      description_km: category.description_km || '',

      slug: category.slug || '',
      is_active: category.is_active ?? true,
      order: category.order ?? 0,
    });

    setCategoryImageFile(null);

    setCategoryImagePreview(
      getImageUrl(category.image_url || '')
    );

    if (categoryFileRef.current) {
      categoryFileRef.current.value = '';
    }

    setCategoryModalOpen(true);
  };

  const handleCategorySubmit = async (event) => {
    event.preventDefault();

    const currentName =
      categoryFormData[`name_${langSuffix}`]?.trim();

    if (!currentName) {
      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលឈ្មោះប្រភេទវគ្គសិក្សា។'
          : 'Category name is required.'
      );

      return;
    }

    if (!categoryFormData.slug.trim()) {
      toast.error(
        tr(
          'courses.categorySlugRequired',
          'Category slug is required.',
          'សូមបញ្ចូល Slug របស់ប្រភេទវគ្គសិក្សា។'
        )
      );

      return;
    }

    try {
      setCategorySubmitting(true);

      const payload = new FormData();

      const nameEn =
        categoryFormData.name_en.trim() ||
        currentName;

      const nameKm =
        categoryFormData.name_km.trim() ||
        currentName;

      payload.append(
        'name_en',
        nameEn
      );

      payload.append(
        'description_en',
        categoryFormData.description_en.trim()
      );

      payload.append(
        'name_km',
        nameKm
      );

      payload.append(
        'description_km',
        categoryFormData.description_km.trim()
      );

      payload.append(
        'slug',
        createSlug(categoryFormData.slug)
      );

      payload.append(
        'is_active',
        String(categoryFormData.is_active)
      );

      payload.append(
        'order',
        String(Number(categoryFormData.order) || 0)
      );

      if (categoryImageFile) {
        payload.append(
          'image_file',
          categoryImageFile
        );
      }

      if (editingCategory) {
        await api.put(
          `/api/courses/categories/${editingCategory.id}`,
          payload
        );

        toast.success(
          tr(
            'courses.categoryUpdated',
            'Category updated successfully.',
            'បានកែប្រែប្រភេទវគ្គសិក្សាដោយជោគជ័យ។'
          )
        );
      } else {
        await api.post(
          '/api/courses/categories',
          payload
        );

        toast.success(
          tr(
            'courses.categoryCreated',
            'Category created successfully.',
            'បានបង្កើតប្រភេទវគ្គសិក្សាដោយជោគជ័យ។'
          )
        );
      }

      setCategoryModalOpen(false);
      resetCategoryForm();

      await fetchData();
    } catch (error) {
      console.error(
        'Save category error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.categorySaveFailed',
            'Failed to save category.',
            'មិនអាចរក្សាទុកប្រភេទវគ្គសិក្សាបានទេ។'
          )
        )
      );
    } finally {
      setCategorySubmitting(false);
    }
  };

  const handleDeleteCategory = async (id) => {
    const confirmed = window.confirm(
      tr(
        'courses.categoryDeleteConfirm',
        'Are you sure you want to delete this category?',
        'តើអ្នកប្រាកដថាចង់លុបប្រភេទវគ្គសិក្សានេះមែនទេ?'
      )
    );

    if (!confirmed) {
      return;
    }

    try {
      await api.delete(
        `/api/courses/categories/${id}`
      );

      toast.success(
        tr(
          'courses.categoryDeleted',
          'Category deleted successfully.',
          'បានលុបប្រភេទវគ្គសិក្សាដោយជោគជ័យ។'
        )
      );

      await fetchData();
    } catch (error) {
      console.error(
        'Delete category error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          tr(
            'courses.categoryDeleteFailed',
            'Failed to delete category.',
            'មិនអាចលុបប្រភេទវគ្គសិក្សាបានទេ។'
          )
        )
      );
    }
  };

  const activeCourses = courses.filter(
    (course) => course.is_active
  ).length;

  const featuredCourses = courses.filter(
    (course) => course.is_featured
  ).length;

  const activeCategories = categories.filter(
    (category) => category.is_active
  ).length;

  const courseColumns = [
    {
      key: 'image_url',
      label: tr(
        'courses.image',
        'Image',
        'រូបភាព'
      ),

      render: (value, row) => {
        const image = row.image_url || '';

        if (!image) {
          return (
            <div className="w-16 h-12 rounded-lg bg-blue-50 flex items-center justify-center text-blue-900 border border-blue-100">
              <FiBookOpen size={20} />
            </div>
          );
        }

        return (
          <img
            src={getImageUrl(image)}
            alt={
              getCourseValue(row, 'title') ||
              'Course'
            }
            className="w-16 h-12 object-cover rounded-lg border border-blue-200"
            onError={(event) => {
              event.currentTarget.style.display =
                'none';
            }}
          />
        );
      },
    },

    {
      key: `title_${langSuffix}`,

      label: tr(
        'courses.course',
        'Course',
        'វគ្គសិក្សា'
      ),

      render: (value, row) => {
        const title = getCourseValue(
          row,
          'title'
        );

        const description =
          getCourseValue(
            row,
            'short_description'
          ) ||
          getCourseValue(
            row,
            'description'
          );

        return (
          <div className="max-w-[260px]">
            <p className="text-sm font-bold text-blue-900 truncate">
              {title ||
                tr(
                  'courses.untitled',
                  'Untitled',
                  'គ្មានចំណងជើង'
                )}
            </p>

            {description && (
              <p className="text-xs text-blue-400 truncate mt-1">
                {description}
              </p>
            )}
          </div>
        );
      },
    },

    {
      key: 'category_id',

      label: tr(
        'courses.category',
        'Category',
        'ប្រភេទ'
      ),

      render: (value, row) => (
        <span className="inline-flex px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 text-xs font-semibold">
          {getCourseCategoryName(row)}
        </span>
      ),
    },

    {
      key: `level_${langSuffix}`,

      label: tr(
        'courses.level',
        'Level',
        'កម្រិត'
      ),

      render: (value, row) => (
        <span className="text-sm text-blue-500">
          {getCourseValue(row, 'level') ||
            '-'}
        </span>
      ),
    },

    {
      key: `duration_${langSuffix}`,

      label: tr(
        'courses.duration',
        'Duration',
        'រយៈពេល'
      ),

      render: (value, row) => (
        <span className="text-sm text-blue-500">
          {getCourseValue(
            row,
            'duration'
          ) || '-'}
        </span>
      ),
    },

    {
      key: 'price',

      label: tr(
        'courses.price',
        'Price',
        'តម្លៃ'
      ),

      render: (value) => (
        <span className="text-sm font-semibold text-blue-900">
          {value !== null &&
          value !== undefined &&
          value !== ''
            ? `$${value}`
            : tr(
                'courses.free',
                'Free',
                'ឥតគិតថ្លៃ'
              )}
        </span>
      ),
    },

    {
      key: 'is_active',

      label: tr(
        'common.status',
        'Status',
        'ស្ថានភាព'
      ),

      render: (value) => (
        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-xs
            font-semibold
            ${
              value
                ? 'bg-green-50 text-green-700 border border-green-200'
                : 'bg-red-50 text-red-600 border border-red-200'
            }
          `}
        >
          <span
            className={`w-1.5 h-1.5 rounded-full ${
              value
                ? 'bg-green-500'
                : 'bg-red-500'
            }`}
          />

          {value
            ? tr(
                'common.active',
                'Active',
                'សកម្ម'
              )
            : tr(
                'common.inactive',
                'Inactive',
                'អសកម្ម'
              )}
        </span>
      ),
    },

    {
      key: 'actions',

      label: tr(
        'common.actions',
        'Actions',
        'សកម្មភាព'
      ),

      render: (value, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handleEditCourse(row)
            }
            title={tr(
              'courses.editCourse',
              'Edit Course',
              'កែប្រែវគ្គសិក្សា'
            )}
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-blue-50 text-blue-900 hover:bg-blue-900 hover:text-white transition"
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCourse(row.id)
            }
            title={tr(
              'courses.deleteCourse',
              'Delete Course',
              'លុបវគ្គសិក្សា'
            )}
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-red-50 text-red-600 hover:bg-red-600 hover:text-white transition"
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  const categoryColumns = [
    {
      key: 'image_url',

      label: tr(
        'courses.image',
        'Image',
        'រូបភាព'
      ),

      render: (value, row) => {
        if (!value) {
          return (
            <div className="w-16 h-12 rounded-lg bg-blue-50 flex items-center justify-center text-blue-900 border border-blue-100">
              <FiLayers size={20} />
            </div>
          );
        }

        return (
          <img
            src={getImageUrl(value)}
            alt={
              getCategoryValue(
                row,
                'name'
              ) || 'Category'
            }
            className="w-16 h-12 object-cover rounded-lg border border-blue-200"
            onError={(event) => {
              event.currentTarget.style.display =
                'none';
            }}
          />
        );
      },
    },

    {
      key: `name_${langSuffix}`,

      label: tr(
        'courses.categoryName',
        'Category Name',
        'ឈ្មោះប្រភេទ'
      ),

      render: (value, row) => (
        <div className="max-w-[250px]">
          <p className="text-sm font-bold text-blue-900 truncate">
            {getCategoryValue(
              row,
              'name'
            ) || '-'}
          </p>

          {getCategoryValue(
            row,
            'description'
          ) && (
            <p className="text-xs text-blue-400 truncate mt-1">
              {getCategoryValue(
                row,
                'description'
              )}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'slug',

      label: tr(
        'courses.slug',
        'Slug',
        'Slug'
      ),

      render: (value) => (
        <span className="text-xs text-blue-500 bg-blue-50 px-2.5 py-1.5 rounded-lg">
          {value || '-'}
        </span>
      ),
    },

    {
      key: 'order',

      label: tr(
        'courses.order',
        'Order',
        'លំដាប់'
      ),

      render: (value) => (
        <span className="inline-flex items-center justify-center w-8 h-8 rounded-lg bg-blue-50 text-blue-900 text-xs font-bold">
          {value ?? 0}
        </span>
      ),
    },

    {
      key: 'is_active',

      label: tr(
        'common.status',
        'Status',
        'ស្ថានភាព'
      ),

      render: (value) => (
        <span
          className={`
            inline-flex
            items-center
            gap-1.5
            px-2.5
            py-1.5
            rounded-full
            text-xs
            font-semibold
            ${
              value
                ? 'bg-green-50 text-green-700 border border-green-200'
                : 'bg-red-50 text-red-600 border border-red-200'
            }
          `}
        >
          <span
            className={`w-1.5 h-1.5 rounded-full ${
              value
                ? 'bg-green-500'
                : 'bg-red-500'
            }`}
          />

          {value
            ? tr(
                'common.active',
                'Active',
                'សកម្ម'
              )
            : tr(
                'common.inactive',
                'Inactive',
                'អសកម្ម'
              )}
        </span>
      ),
    },

    {
      key: 'actions',

      label: tr(
        'common.actions',
        'Actions',
        'សកម្មភាព'
      ),

      render: (value, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handleEditCategory(row)
            }
            title={tr(
              'courses.editCategory',
              'Edit Category',
              'កែប្រែប្រភេទ'
            )}
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-blue-50 text-blue-900 hover:bg-blue-900 hover:text-white transition"
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCategory(row.id)
            }
            title={tr(
              'courses.deleteCategory',
              'Delete Category',
              'លុបប្រភេទ'
            )}
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-red-50 text-red-600 hover:bg-red-600 hover:text-white transition"
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div
      className={
        isKhmer
          ? 'w-full font-khmer'
          : 'w-full font-english'
      }
    >
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 mb-6">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 bg-blue-900 text-white rounded-xl flex items-center justify-center shadow-sm">
            <FiBookOpen size={20} />
          </div>

          <div>
            <h1 className="text-xl md:text-2xl font-bold text-blue-900">
              {tr(
                'courses.title',
                'Courses Management',
                'គ្រប់គ្រងវគ្គសិក្សា'
              )}
            </h1>

            <p className="text-xs md:text-sm text-blue-400 mt-1">
              {tr(
                'courses.subtitle',
                'Manage courses and course categories',
                'គ្រប់គ្រងវគ្គសិក្សា និងប្រភេទវគ្គសិក្សា'
              )}
            </p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-2">
          <button
            type="button"
            onClick={handleAddCategory}
            className="h-10 px-4 inline-flex items-center justify-center gap-2 bg-white border border-blue-200 text-blue-900 rounded-lg text-sm font-semibold hover:bg-blue-50 transition"
          >
            <FiPlus size={16} />

            {tr(
              'courses.addCategory',
              'Add Category',
              'បន្ថែមប្រភេទ'
            )}
          </button>

          <button
            type="button"
            onClick={handleAddCourse}
            className="h-10 px-4 inline-flex items-center justify-center gap-2 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 transition"
          >
            <FiPlus size={16} />

            {tr(
              'courses.addCourse',
              'Add Course',
              'បន្ថែមវគ្គសិក្សា'
            )}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 xl:grid-cols-4 gap-3 mb-6">
        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-blue-400">
                {tr(
                  'courses.totalCourses',
                  'Total Courses',
                  'វគ្គសិក្សាសរុប'
                )}
              </p>

              <p className="text-2xl font-bold text-blue-900 mt-1">
                {courses.length}
              </p>
            </div>

            <div className="w-10 h-10 rounded-lg bg-blue-50 text-blue-900 flex items-center justify-center">
              <FiBookOpen size={18} />
            </div>
          </div>
        </div>

        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-blue-400">
                {tr(
                  'courses.activeCourses',
                  'Active Courses',
                  'វគ្គសិក្សាសកម្ម'
                )}
              </p>

              <p className="text-2xl font-bold text-green-600 mt-1">
                {activeCourses}
              </p>
            </div>

            <div className="w-10 h-10 rounded-lg bg-green-50 text-green-600 flex items-center justify-center">
              <FiCheckCircle size={18} />
            </div>
          </div>
        </div>

        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-blue-400">
                {tr(
                  'courses.featuredCourses',
                  'Featured',
                  'វគ្គសិក្សាពិសេស'
                )}
              </p>

              <p className="text-2xl font-bold text-red-600 mt-1">
                {featuredCourses}
              </p>
            </div>

            <div className="w-10 h-10 rounded-lg bg-red-50 text-red-600 flex items-center justify-center">
              <FiStar size={18} />
            </div>
          </div>
        </div>

        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-blue-400">
                {tr(
                  'courses.categories',
                  'Categories',
                  'ប្រភេទវគ្គសិក្សា'
                )}
              </p>

              <p className="text-2xl font-bold text-blue-600 mt-1">
                {activeCategories}
              </p>
            </div>

            <div className="w-10 h-10 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center">
              <FiLayers size={18} />
            </div>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-2 mb-4 p-1 bg-blue-50 rounded-xl w-fit">
        <button
          type="button"
          onClick={() =>
            setActiveTab('courses')
          }
          className={`
            h-10
            px-4
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition
            ${
              activeTab === 'courses'
                ? 'bg-blue-900 text-white shadow-sm'
                : 'text-blue-500 hover:bg-white'
            }
          `}
        >
          <FiBookOpen size={16} />

          {tr(
            'courses.courses',
            'Courses',
            'វគ្គសិក្សា'
          )}

          <span
            className={`
              min-w-[24px]
              h-6
              px-1.5
              rounded-md
              text-xs
              flex
              items-center
              justify-center
              ${
                activeTab === 'courses'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {courses.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() =>
            setActiveTab('categories')
          }
          className={`
            h-10
            px-4
            rounded-lg
            text-sm
            font-semibold
            flex
            items-center
            gap-2
            transition
            ${
              activeTab === 'categories'
                ? 'bg-blue-900 text-white shadow-sm'
                : 'text-blue-500 hover:bg-white'
            }
          `}
        >
          <FiLayers size={16} />

          {tr(
            'courses.categories',
            'Categories',
            'ប្រភេទ'
          )}

          <span
            className={`
              min-w-[24px]
              h-6
              px-1.5
              rounded-md
              text-xs
              flex
              items-center
              justify-center
              ${
                activeTab === 'categories'
                  ? 'bg-white/20'
                  : 'bg-white'
              }
            `}
          >
            {categories.length}
          </span>
        </button>
      </div>

      <AdminCard className="overflow-hidden border border-blue-200 rounded-xl shadow-sm">
        {activeTab === 'courses' ? (
          <AdminTable
            columns={courseColumns}
            data={courses}
            loading={loading}
          />
        ) : (
          <AdminTable
            columns={categoryColumns}
            data={categories}
            loading={loading}
          />
        )}
      </AdminCard>

      <AdminModal
        isOpen={courseModalOpen}
        onClose={closeCourseModal}
        title={
          editingCourse
            ? tr(
                'courses.editCourse',
                'Edit Course',
                'កែប្រែវគ្គសិក្សា'
              )
            : tr(
                'courses.createCourse',
                'Create Course',
                'បង្កើតវគ្គសិក្សា'
              )
        }
      >
        <form onSubmit={handleCourseSubmit}>
          <div className="space-y-5">
            <div className="border border-blue-200 rounded-xl overflow-hidden">
              <div className="flex items-center gap-2 px-4 py-3 bg-blue-50 border-b border-blue-200">
                <FiGlobe className="text-blue-900" />

                <h3 className="text-sm font-bold text-blue-900">
                  {isKhmer
                    ? 'មាតិកាភាសាខ្មែរ'
                    : 'English Content'}
                </h3>
              </div>

              <div className="p-4 space-y-4">
                <div>
                  <label className="admin-label">
                    {isKhmer
                      ? 'ចំណងជើងវគ្គសិក្សា'
                      : 'Course Title'}

                    <span className="text-red-600 ml-1">
                      *
                    </span>
                  </label>

                  <input
                    type="text"
                    name={`title_${langSuffix}`}
                    value={
                      courseFormData[
                        `title_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    className={`admin-input ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'ការអភិវឌ្ឍគេហទំព័រ'
                        : 'Web Development'
                    }
                    required
                  />
                </div>

                <div>
                  <label className="admin-label">
                    {isKhmer
                      ? 'ការពិពណ៌នាខ្លី'
                      : 'Short Description'}
                  </label>

                  <textarea
                    name={`short_description_${langSuffix}`}
                    value={
                      courseFormData[
                        `short_description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    rows={2}
                    className={`admin-input resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាខ្លីអំពីវគ្គសិក្សា'
                        : 'Short course description'
                    }
                  />
                </div>

                <div>
                  <label className="admin-label">
                    {isKhmer
                      ? 'ការពិពណ៌នា'
                      : 'Description'}
                  </label>

                  <textarea
                    name={`description_${langSuffix}`}
                    value={
                      courseFormData[
                        `description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCourseInputChange
                    }
                    rows={4}
                    className={`admin-input resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាពេញលេញអំពីវគ្គសិក្សា'
                        : 'Enter full course description'
                    }
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="admin-label">
                      {isKhmer
                        ? 'រយៈពេល'
                        : 'Duration'}
                    </label>

                    <input
                      type="text"
                      name={`duration_${langSuffix}`}
                      value={
                        courseFormData[
                          `duration_${langSuffix}`
                        ]
                      }
                      onChange={
                        handleCourseInputChange
                      }
                      className={`admin-input ${
                        isKhmer
                          ? 'font-khmer'
                          : 'font-english'
                      }`}
                      placeholder={
                        isKhmer
                          ? '៣ ខែ'
                          : '3 Months'
                      }
                    />
                  </div>

                  <div>
                    <label className="admin-label">
                      {isKhmer
                        ? 'កម្រិត'
                        : 'Level'}
                    </label>

                    <input
                      type="text"
                      name={`level_${langSuffix}`}
                      value={
                        courseFormData[
                          `level_${langSuffix}`
                        ]
                      }
                      onChange={
                        handleCourseInputChange
                      }
                      className={`admin-input ${
                        isKhmer
                          ? 'font-khmer'
                          : 'font-english'
                      }`}
                      placeholder={
                        isKhmer
                          ? 'កម្រិតដំបូង'
                          : 'Beginner'
                      }
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="border border-blue-200 rounded-xl p-4 space-y-4">
              <h3 className="text-sm font-bold text-blue-900">
                {tr(
                  'courses.generalInformation',
                  'General Information',
                  'ព័ត៌មានទូទៅ'
                )}
              </h3>

              <div>
                <label className="admin-label">
                  Slug *
                </label>

                <input
                  type="text"
                  name="slug"
                  value={courseFormData.slug}
                  onChange={
                    handleCourseInputChange
                  }
                  className="admin-input"
                  placeholder="web-development"
                  required
                />
              </div>

              <div>
                <label className="admin-label">
                  {tr(
                    'courses.category',
                    'Category',
                    'ប្រភេទ'
                  )}

                  <span className="text-red-600 ml-1">
                    *
                  </span>
                </label>

                <select
                  name="category_id"
                  value={
                    courseFormData.category_id
                  }
                  onChange={
                    handleCourseInputChange
                  }
                  className="admin-input"
                  required
                >
                  <option value="">
                    {tr(
                      'courses.selectCategory',
                      'Select Category',
                      'ជ្រើសរើសប្រភេទ'
                    )}
                  </option>

                  {categories
                    .filter(
                      (category) =>
                        category.is_active !==
                        false
                    )
                    .map((category) => (
                      <option
                        key={category.id}
                        value={category.id}
                      >
                        {getCategoryValue(
                          category,
                          'name'
                        )}
                      </option>
                    ))}
                </select>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="admin-label">
                    {tr(
                      'courses.price',
                      'Price',
                      'តម្លៃ'
                    )}
                  </label>

                  <input
                    type="text"
                    name="price"
                    value={courseFormData.price}
                    onChange={
                      handleCourseInputChange
                    }
                    className="admin-input"
                    placeholder="0"
                  />
                </div>

                <div>
                  <label className="admin-label">
                    {tr(
                      'courses.displayOrder',
                      'Display Order',
                      'លំដាប់បង្ហាញ'
                    )}
                  </label>

                  <input
                    type="number"
                    name="order"
                    min="0"
                    value={courseFormData.order}
                    onChange={
                      handleCourseInputChange
                    }
                    className="admin-input"
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="admin-label">
                {tr(
                  'courses.courseImage',
                  'Course Image',
                  'រូបភាពវគ្គសិក្សា'
                )}
              </label>

              {!courseImagePreview ? (
                <div
                  onClick={() =>
                    courseFileRef.current?.click()
                  }
                  className="min-h-[150px] border-2 border-dashed border-blue-200 rounded-xl flex flex-col items-center justify-center cursor-pointer bg-blue-50 hover:border-blue-900 transition"
                >
                  <input
                    ref={courseFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCourseImageChange
                    }
                    className="hidden"
                  />

                  <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-blue-900 border border-blue-200 mb-3">
                    <FiUploadCloud size={23} />
                  </div>

                  <p className="text-sm font-semibold text-blue-900">
                    {tr(
                      'courses.uploadImage',
                      'Upload Course Image',
                      'បញ្ចូលរូបភាពវគ្គសិក្សា'
                    )}
                  </p>

                  <p className="text-xs text-blue-400 mt-1">
                    JPG, JPEG, PNG, WEBP — 5 MB
                  </p>
                </div>
              ) : (
                <div className="relative h-[220px] rounded-xl overflow-hidden border border-blue-200 bg-blue-50 group">
                  <img
                    src={courseImagePreview}
                    alt="Course Preview"
                    className="w-full h-full object-cover"
                  />

                  <button
                    type="button"
                    onClick={removeCourseImage}
                    className="absolute top-3 right-3 w-9 h-9 rounded-lg bg-red-600 text-white flex items-center justify-center hover:bg-red-700 shadow"
                  >
                    <FiX size={18} />
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      courseFileRef.current?.click()
                    }
                    className="absolute bottom-3 right-3 h-9 px-3 bg-white text-blue-900 rounded-lg text-xs font-semibold shadow"
                  >
                    {tr(
                      'courses.changeImage',
                      'Change Image',
                      'ប្ដូររូបភាព'
                    )}
                  </button>

                  <input
                    ref={courseFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCourseImageChange
                    }
                    className="hidden"
                  />
                </div>
              )}
            </div>

            <label className="flex items-center justify-between gap-3 p-4 border border-blue-200 rounded-xl bg-blue-50 cursor-pointer">
              <div className="flex items-center gap-3">
                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center
                    ${
                      courseFormData.is_active
                        ? 'bg-green-100 text-green-600'
                        : 'bg-blue-100 text-blue-400'
                    }
                  `}
                >
                  {courseFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p className="text-sm font-semibold text-blue-900">
                    {tr(
                      'courses.activeCourse',
                      'Active Course',
                      'វគ្គសិក្សាសកម្ម'
                    )}
                  </p>

                  <p className="text-xs text-blue-400">
                    {tr(
                      'courses.activeCourseHelp',
                      'Show this course on the website',
                      'បង្ហាញវគ្គសិក្សានេះនៅលើគេហទំព័រ'
                    )}
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                name="is_active"
                checked={
                  courseFormData.is_active
                }
                onChange={
                  handleCourseInputChange
                }
                className="w-4 h-4 accent-blue-900"
              />
            </label>

            <label className="flex items-center justify-between gap-3 p-4 border border-blue-200 rounded-xl bg-blue-50 cursor-pointer">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg flex items-center justify-center bg-red-50 text-red-600">
                  <FiStar />
                </div>

                <div>
                  <p className="text-sm font-semibold text-blue-900">
                    {tr(
                      'courses.featuredCourse',
                      'Featured Course',
                      'វគ្គសិក្សាពិសេស'
                    )}
                  </p>

                  <p className="text-xs text-blue-400">
                    {tr(
                      'courses.featuredHelp',
                      'Display this course in featured sections',
                      'បង្ហាញវគ្គសិក្សានេះនៅផ្នែកវគ្គសិក្សាពិសេស'
                    )}
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                name="is_featured"
                checked={
                  courseFormData.is_featured
                }
                onChange={
                  handleCourseInputChange
                }
                className="w-4 h-4 accent-red-600"
              />
            </label>
          </div>

          <div className="mt-6 pt-4 border-t border-blue-200 flex flex-col-reverse sm:flex-row justify-end gap-3">
            <button
              type="button"
              onClick={closeCourseModal}
              disabled={courseSubmitting}
              className="h-10 px-4 bg-white border border-blue-200 text-blue-500 rounded-lg text-sm font-semibold hover:bg-blue-50 disabled:opacity-50"
            >
              {tr(
                'common.cancel',
                'Cancel',
                'បោះបង់'
              )}
            </button>

            <button
              type="submit"
              disabled={courseSubmitting}
              className="min-w-[140px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {courseSubmitting
                ? editingCourse
                  ? tr(
                      'courses.updating',
                      'Updating...',
                      'កំពុងកែប្រែ...'
                    )
                  : tr(
                      'courses.creating',
                      'Creating...',
                      'កំពុងបង្កើត...'
                    )
                : editingCourse
                ? tr(
                    'courses.updateCourse',
                    'Update Course',
                    'រក្សាទុកការកែប្រែ'
                  )
                : tr(
                    'courses.createCourse',
                    'Create Course',
                    'បង្កើតវគ្គសិក្សា'
                  )}
            </button>
          </div>
        </form>
      </AdminModal>

      <AdminModal
        isOpen={categoryModalOpen}
        onClose={closeCategoryModal}
        title={
          editingCategory
            ? tr(
                'courses.editCategory',
                'Edit Category',
                'កែប្រែប្រភេទ'
              )
            : tr(
                'courses.createCategory',
                'Create Category',
                'បង្កើតប្រភេទ'
              )
        }
      >
        <form onSubmit={handleCategorySubmit}>
          <div className="space-y-5">
            <div className="border border-blue-200 rounded-xl overflow-hidden">
              <div className="flex items-center gap-2 px-4 py-3 bg-blue-50 border-b border-blue-200">
                <FiGlobe className="text-blue-900" />

                <h3 className="text-sm font-bold text-blue-900">
                  {isKhmer
                    ? 'មាតិកាភាសាខ្មែរ'
                    : 'English Content'}
                </h3>
              </div>

              <div className="p-4 space-y-4">
                <div>
                  <label className="admin-label">
                    {isKhmer
                      ? 'ឈ្មោះប្រភេទ'
                      : 'Category Name'}

                    <span className="text-red-600 ml-1">
                      *
                    </span>
                  </label>

                  <input
                    type="text"
                    name={`name_${langSuffix}`}
                    value={
                      categoryFormData[
                        `name_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCategoryInputChange
                    }
                    className={`admin-input ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'វគ្គសិក្សាព័ត៌មានវិទ្យា'
                        : 'IT Courses'
                    }
                    required
                  />
                </div>

                <div>
                  <label className="admin-label">
                    {isKhmer
                      ? 'ការពិពណ៌នា'
                      : 'Description'}
                  </label>

                  <textarea
                    name={`description_${langSuffix}`}
                    value={
                      categoryFormData[
                        `description_${langSuffix}`
                      ]
                    }
                    onChange={
                      handleCategoryInputChange
                    }
                    rows={3}
                    className={`admin-input resize-none ${
                      isKhmer
                        ? 'font-khmer'
                        : 'font-english'
                    }`}
                    placeholder={
                      isKhmer
                        ? 'បញ្ចូលការពិពណ៌នាប្រភេទវគ្គសិក្សា'
                        : 'Enter category description'
                    }
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="admin-label">
                Slug *
              </label>

              <input
                type="text"
                name="slug"
                value={categoryFormData.slug}
                onChange={
                  handleCategoryInputChange
                }
                className="admin-input"
                placeholder="it-courses"
                required
              />
            </div>

            <div>
              <label className="admin-label">
                {tr(
                  'courses.categoryImage',
                  'Category Image',
                  'រូបភាពប្រភេទ'
                )}
              </label>

              {!categoryImagePreview ? (
                <div
                  onClick={() =>
                    categoryFileRef.current?.click()
                  }
                  className="min-h-[140px] border-2 border-dashed border-blue-200 rounded-xl flex flex-col items-center justify-center cursor-pointer bg-blue-50 hover:border-blue-900 transition"
                >
                  <input
                    ref={categoryFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCategoryImageChange
                    }
                    className="hidden"
                  />

                  <FiImage
                    size={25}
                    className="text-blue-900 mb-2"
                  />

                  <p className="text-sm font-semibold text-blue-900">
                    {tr(
                      'courses.uploadCategoryImage',
                      'Upload Category Image',
                      'បញ្ចូលរូបភាពប្រភេទ'
                    )}
                  </p>

                  <p className="text-xs text-blue-400 mt-1">
                    JPG, JPEG, PNG, WEBP — 5 MB
                  </p>
                </div>
              ) : (
                <div className="relative h-[200px] rounded-xl overflow-hidden border border-blue-200">
                  <img
                    src={categoryImagePreview}
                    alt="Category Preview"
                    className="w-full h-full object-cover"
                  />

                  <button
                    type="button"
                    onClick={removeCategoryImage}
                    className="absolute top-3 right-3 w-9 h-9 rounded-lg bg-red-600 text-white flex items-center justify-center hover:bg-red-700 shadow"
                  >
                    <FiX size={18} />
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      categoryFileRef.current?.click()
                    }
                    className="absolute bottom-3 right-3 h-9 px-3 bg-white text-blue-900 rounded-lg text-xs font-semibold shadow"
                  >
                    {tr(
                      'courses.changeImage',
                      'Change Image',
                      'ប្ដូររូបភាព'
                    )}
                  </button>

                  <input
                    ref={categoryFileRef}
                    type="file"
                    accept="image/jpeg,image/jpg,image/png,image/webp"
                    onChange={
                      handleCategoryImageChange
                    }
                    className="hidden"
                  />
                </div>
              )}
            </div>

            <div>
              <label className="admin-label">
                {tr(
                  'courses.displayOrder',
                  'Display Order',
                  'លំដាប់បង្ហាញ'
                )}
              </label>

              <input
                type="number"
                name="order"
                min="0"
                value={categoryFormData.order}
                onChange={
                  handleCategoryInputChange
                }
                className="admin-input"
              />
            </div>

            <label className="flex items-center justify-between gap-3 p-4 border border-blue-200 rounded-xl bg-blue-50 cursor-pointer">
              <div className="flex items-center gap-3">
                <div
                  className={`
                    w-9
                    h-9
                    rounded-lg
                    flex
                    items-center
                    justify-center
                    ${
                      categoryFormData.is_active
                        ? 'bg-green-100 text-green-600'
                        : 'bg-blue-100 text-blue-400'
                    }
                  `}
                >
                  {categoryFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p className="text-sm font-semibold text-blue-900">
                    {tr(
                      'courses.activeCategory',
                      'Active Category',
                      'ប្រភេទសកម្ម'
                    )}
                  </p>

                  <p className="text-xs text-blue-400">
                    {tr(
                      'courses.activeCategoryHelp',
                      'Show this category on the website',
                      'បង្ហាញប្រភេទនេះនៅលើគេហទំព័រ'
                    )}
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                name="is_active"
                checked={
                  categoryFormData.is_active
                }
                onChange={
                  handleCategoryInputChange
                }
                className="w-4 h-4 accent-blue-900"
              />
            </label>
          </div>

          <div className="mt-6 pt-4 border-t border-blue-200 flex flex-col-reverse sm:flex-row justify-end gap-3">
            <button
              type="button"
              onClick={closeCategoryModal}
              disabled={categorySubmitting}
              className="h-10 px-4 bg-white border border-blue-200 text-blue-500 rounded-lg text-sm font-semibold hover:bg-blue-50 disabled:opacity-50"
            >
              {tr(
                'common.cancel',
                'Cancel',
                'បោះបង់'
              )}
            </button>

            <button
              type="submit"
              disabled={categorySubmitting}
              className="min-w-[150px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {categorySubmitting
                ? editingCategory
                  ? tr(
                      'courses.updating',
                      'Updating...',
                      'កំពុងកែប្រែ...'
                    )
                  : tr(
                      'courses.creating',
                      'Creating...',
                      'កំពុងបង្កើត...'
                    )
                : editingCategory
                ? tr(
                    'courses.updateCategory',
                    'Update Category',
                    'រក្សាទុកការកែប្រែ'
                  )
                : tr(
                    'courses.createCategory',
                    'Create Category',
                    'បង្កើតប្រភេទ'
                  )}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
